INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (1,4.9,31,'I find it rewarding when a small piece of guidance helps a learner become more independent. I care about leaving behind notes that make the next contribution easier. We make space for independent exploration followed by a thoughtful review. Progress is discussed openly, with room to question assumptions and revise the approach.','Rust utilities with cross-platform tests; Git, issue triage and reproducible builds; reviewable patches and community feedback; issue triage and reproducible bug reports; clear technical notes.','A cross-functional group is maintaining a test harness for a widely used parser. We value thoughtful questions, small experiments and a willingness to document learning. A useful contribution could be to write a contributor note from a newcomer perspective. The first milestone can lead to a clear before-and-after measure for a real user journey. The first days focus on setup and context; after that we agree on a deliverable together.','["This should help safer handling of test data and technical changes.","A related benefit is better access for people using assistive technology.","The team is exploring a test harness for a widely used parser, so the result can inform a practical next step."]');
INSERT INTO hostlist_hosts (id,fullname,company,country,city,primary_domain,secondary_domain,primary_country,secondary_country,languages) VALUES (2,'Wren Marble Fuzzleford','Make-Believe Blueberry Accordion Studio 002','Italy','Milan','Cybersecurity','Application Security','Italy','Italy','Italian, English');
INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (2,9.9,17,'I enjoy helping people connect technical choices to the needs behind a product. I make time for practical feedback, not just a final review. We are happy to explain the context behind the work before choosing a task. The team values readable decisions, careful feedback and steady delivery.','Python automation and threat modelling; cloud identity policy and audit trails; detection rules and incident documentation; application testing in isolated labs; clear technical notes.','Our small team is currently shaping a practical application-security training lab. The project suits someone who wants feedback and is comfortable sharing progress. The initial task could focus on review a permission boundary with a mentor. The first milestone can lead to a prototype reviewed by teammates and a small set of intended users. We use short demos and written notes so learning does not depend on being in one meeting.','["The team will measure success through a more approachable path for a new team member.","A related benefit is more predictable releases with fewer last-minute surprises.","The team is exploring a practical application-security training lab, so the result can inform a practical next step."]');
