INSERT INTO hostlist_hosts (id,fullname,company,country,city,primary_domain,secondary_domain,primary_country,secondary_country,languages) VALUES (23,'Bela Pancake Wizzlebrook','Make-Believe Marble Meadow Studio 023','Italy','Milan','Open Source Software','Developer Tools','Italy','Italy','Italian, English');
INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (23,2.6,16,'We would like to exchange practical knowledge while building something that has a clear user. I like connecting a learner with the product context behind a ticket. The first milestone can be adjusted once the learner sees the codebase. A practical outcome matters more than a polished presentation.','Python packages and CI workflows; TypeScript developer tools and release automation; version control practices and contributor handovers; maintainer workflows and regression tests; clear technical notes.','We are iterating on a small library used by civic organisations. The project suits someone who wants feedback and is comfortable sharing progress. Depending on your interests, you might improve an example and verify it against the current API. The first milestone can lead to a clear before-and-after measure for a real user journey. A senior teammate will help define a bounded task and give feedback at each milestone.','["A useful outcome would give better access for people using assistive technology.","A related benefit is faster discovery of issues while they are still easy to fix.","The team is exploring a small library used by civic organisations, so the result can inform a practical next step."]');
