INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (24,3.6,13,'Sharing the reasoning behind my work is one of the most useful parts of collaborating. I care about leaving behind notes that make the next contribution easier. We can introduce the people who use the product when that helps with context. The team values readable decisions, careful feedback and steady delivery.','accessible map interfaces and API tests; TypeScript maps and vector tiles; open-data pipelines and metadata documentation; map accessibility and visual encoding reviews; clear technical notes.','We are preparing the next version of a neighbourhood change explorer. A learner with an interest in practical teamwork will have room to contribute. A useful contribution could be to compare two visual encodings with a small user test. The first milestone can lead to an improvement that reduces avoidable manual work. A senior teammate will help define a bounded task and give feedback at each milestone.','["We hope this change will support less repeated manual checking for the product team.","A related benefit is more predictable releases with fewer last-minute surprises.","The team is exploring a neighbourhood change explorer, so the result can inform a practical next step."]');
