INSERT INTO hostlist_hosts (id,fullname,company,country,city,primary_domain,secondary_domain,primary_country,secondary_country,languages) VALUES (107,'Ivo Comet Puddlewick','Make-Believe Pebble Telescope Studio 107','Italy','Turin','Cloud Computing','Platform Engineering','Italy','Italy','Italian, English');
INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (107,3.0,13,'I find it rewarding when a small piece of guidance helps a learner become more independent. I appreciate a fresh perspective on decisions we have become used to. There is space to learn the release and review habits used by the team. The work is scoped so a learner can own a useful slice and explain the trade-offs.','Terraform, containers and GitHub Actions; Kubernetes manifests and service metrics; reliable build pipelines and operational notes; container workflows and deployment checks; clear technical notes.','Our small team is currently shaping a repeatable release pipeline for container apps. Someone who can explain their reasoning will find plenty to explore here. A useful contribution could be to make an environment reproducible from a clean checkout. The first milestone can lead to a reusable example that helps the next contributor get started. Mentoring is flexible: code review, design critique or problem-solving sessions depending on the task.','["The team will measure success through safer handling of test data and technical changes.","A related benefit is faster discovery of issues while they are still easy to fix.","The team is exploring a repeatable release pipeline for container apps, so the result can inform a practical next step."]');
INSERT INTO hostlist_hosts (id,fullname,company,country,city,primary_domain,secondary_domain,primary_country,secondary_country,languages) VALUES (108,'Bela Pancake Doodlefern','Fable Moonlit Cloud Cooperative 108','Italy','Turin','Cybersecurity','Incident Response','Italy','Italy','Italian, English, French, Spanish');
INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (108,2.0,33,'I like creating a calm space where a newcomer can ask precise questions and try an idea. I enjoy explaining trade-offs using examples from the work at hand. We make space for independent exploration followed by a thoughtful review. The work is scoped so a learner can own a useful slice and explain the trade-offs.','OWASP testing and secure code review; Python automation and threat modelling; application testing in isolated labs; remediation tracking and security automation; clear technical notes.','The studio has recently started rebuilding a cloud permission review toolkit. You do not need to arrive as an expert; we agree a realistic scope together. One possible starting point is to reproduce a safe lab finding and write a remediation note. The first milestone can lead to a prototype reviewed by teammates and a small set of intended users. The team offers a weekly check-in and encourages questions in a shared project channel.','["A good result would mean more reliable feedback before a change reaches production.","A related benefit is a more approachable path for a new team member.","The team is exploring a cloud permission review toolkit, so the result can inform a practical next step."]');
