INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (170,2.4,6,'We would like to exchange practical knowledge while building something that has a clear user. I want people to feel comfortable proposing a different solution. The contribution should be visible enough for the learner to explain with confidence. The work is scoped so a learner can own a useful slice and explain the trade-offs.','Python services and PostgreSQL; Go microservices and observability; product experiments and technical acceptance criteria; continuous integration and release notes; clear technical notes.','A cross-functional group is maintaining a mobile companion for field specialists. We value thoughtful questions, small experiments and a willingness to document learning. We can shape a first milestone around trace a slow request through the service boundary. The first milestone can lead to a small tool or workflow the team can keep using. A senior teammate will help define a bounded task and give feedback at each milestone.','["The expected benefit is fewer confusing steps for first-time users.","A related benefit is more reliable feedback before a change reaches production.","The team is exploring a mobile companion for field specialists, so the result can inform a practical next step."]');
INSERT INTO hostlist_hosts (id,fullname,company,country,city,primary_domain,secondary_domain,primary_country,secondary_country,languages) VALUES (171,'Rumi Marmalade Wobbleby','Cloudberry Mossy Accordion Atelier 171','Spain','Madrid','Cybersecurity','Application Security','Spain','Spain','Spanish, English');
INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (171,7.8,4,'Good mentoring makes room for curiosity, disagreement and a second attempt. I make time for practical feedback, not just a final review. The exchange can include a short demo of the result to the wider team. We keep the backlog flexible and choose a contribution together after an initial conversation.','OWASP testing and secure code review; Linux hardening and container scanning; secure code review and dependency analysis; identity policy and least-privilege checks; clear technical notes.','Our small team is currently shaping a secure onboarding path for a SaaS service. Someone who can explain their reasoning will find plenty to explore here. We are looking for someone who can add a security check to a development pipeline. The first milestone can lead to a tested feature that can be included in the next release. The team offers a weekly check-in and encourages questions in a shared project channel.','["A good result would mean more predictable releases with fewer last-minute surprises.","A related benefit is more reliable feedback before a change reaches production.","The team is exploring a secure onboarding path for a SaaS service, so the result can inform a practical next step."]');
