INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (233,12.3,40,'I like creating a calm space where a newcomer can ask precise questions and try an idea. I learn from seeing how someone new interprets an old workflow. We are happy to explain the context behind the work before choosing a task. The work is scoped so a learner can own a useful slice and explain the trade-offs.','Linux, shell scripting and deployment checks; OpenTelemetry, dashboards and incident runbooks; resource profiling and cost-aware changes; container workflows and deployment checks; clear technical notes.','A cross-functional group is maintaining a lower-cost test environment. You do not need to arrive as an expert; we agree a realistic scope together. A useful contribution could be to add a useful signal to a service dashboard. The first milestone can lead to an improvement that reduces avoidable manual work. A weekly pairing session is available, with short async reviews between meetings.','["The expected benefit is more reliable feedback before a change reaches production.","A related benefit is better access for people using assistive technology.","The team is exploring a lower-cost test environment, so the result can inform a practical next step."]');
