INSERT INTO hostlist_host_details (host_id,host_experience_years,team_size,motivation,specific_skills,offer_extra_info,business_impact) VALUES (424,2.8,38,'I enjoy helping people connect technical choices to the needs behind a product. I make time for practical feedback, not just a final review. A small retrospective helps us improve the experience for the next person. We keep the backlog flexible and choose a contribution together after an initial conversation.','Python raster processing and reproducible jobs; accessible map interfaces and API tests; GeoJSON validation and reproducible processing; spatial SQL and provenance checks; clear technical notes.','The studio has recently started rebuilding a neighbourhood change explorer. You do not need to arrive as an expert; we agree a realistic scope together. We are looking for someone who can make a map interaction usable without a pointer. The first milestone can lead to a clear before-and-after measure for a real user journey. You can choose between guided pairing and a small independent task with two review checkpoints.','["This should help more predictable releases with fewer last-minute surprises.","A related benefit is a more approachable path for a new team member.","The team is exploring a neighbourhood change explorer, so the result can inform a practical next step."]');
